begin;
select plan(10);
select ok(to_regprocedure('workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)') is not null and to_regprocedure('workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)') is not null,'authorized result and comparison functions exist');
select ok((select bool_and(r.rolname='workspace_query_owner') from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid in ('workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure,'workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)'::regprocedure)),'authorized operations retain the query owner');
select ok((select bool_and(p.prosecdef) and bool_and(regexp_replace(array_to_string(p.proconfig,','),'\s+','','g') in ('search_path=pg_catalog,workspace_private,public,pg_temp','search_path=pg_catalog,workspace_api,pg_temp')) from pg_proc p where p.oid in ('workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure,'workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)'::regprocedure)),'authorized operations are security definers with pinned search paths');
select ok(has_function_privilege('authenticated','workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)','EXECUTE') and has_function_privilege('authenticated','workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)','EXECUTE') and not has_function_privilege('anon','workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)','EXECUTE') and not has_function_privilege('anon','workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)','EXECUTE') and (to_regrole('service_role') is null or (not has_function_privilege('service_role','workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)','EXECUTE') and not has_function_privilege('service_role','workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)','EXECUTE'))),'only authenticated receives the operation ACL');
select ok(not exists(select from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in ('workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure,'workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC retains no execute path');
select ok((select pg_get_functiondef(p.oid) like '%workspace_private.authorized_section_scopes()%' and pg_get_functiondef(p.oid) like '%public.results_exploration_official(%' from pg_proc p where p.oid='workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure),'result delegates authorization and official semantics to their cores');
select ok((select pg_get_functiondef(p.oid) like '%results_exploration_official_wrapper_20260904035355(%' from pg_proc p where p.oid='public.results_exploration_official(uuid,uuid,text,text,text,text,integer,text)'::regprocedure) and (select pg_get_functiondef(p.oid) like '%results_exploration_reporting_level(%' from pg_proc p where p.oid='public.results_exploration_official_wrapper_20260904035355(uuid,uuid,text,text,text,text,integer,text)'::regprocedure) and (select pg_get_functiondef(p.oid) !~ 'rr\.granularity\s*=' from pg_proc p where p.oid='workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure),'category wrapper preserves normalized section semantics without a blanket stored-granularity filter');
select ok((select strpos(d,'left_payload:=workspace_api.official_result')>0 and strpos(d,'right_payload:=workspace_api.official_result')>strpos(d,'left_payload:=workspace_api.official_result') and strpos(d,'ifleft_payload->>''authorization_status''')>strpos(d,'right_payload:=workspace_api.official_result') and strpos(d,'payload:=jsonb_build_object')>strpos(d,'ifright_payload->>''authorization_status''') and d like '%operation_unavailable%' from (select regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g') d from pg_proc p where p.oid='workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)'::regprocedure) x),'comparison authorizes both sides before constructing payload');
select ok((select d like '%official_rows_without_section_identity%' and d like '%''exclusions''%' and d like '%octet_length(payload::text)>120000%' and d like '%''total_bytes''%' and d like '%''truncated''%' and d not like '%''rows''%' and d not like '%''votes''%' from (select regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g') d from pg_proc p where p.oid='workspace_api.official_result(uuid,uuid,text,text,text,text,integer,text)'::regprocedure) x) and (select regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g') like '%octet_length(payload::text)>250000%' from pg_proc p where p.oid='workspace_api.official_comparison(uuid,uuid,text,text,text,text,integer,text,uuid,uuid,text,text,text,text,integer,text)'::regprocedure),'operation payloads expose bounded totals, truncation, and exclusions');
select ok((select i.indisvalid and i.indisready from pg_index i where i.indexrelid='public.result_row_authorized_official_facets_idx'::regclass),'authorized operations retain the bounded official scope index');
select * from finish();
rollback;
